#!/bin/sh
# Checks headers generated from lib/ against xxhash.h:
# - lib/xxhash_root.h, used directly as a multi-file header,
#   must preprocess exactly like xxhash.h;
# - each variant, generated by excluding some units, must preprocess exactly
#   like xxhash.h with the equivalent build macro, and must compile into
#   a library which contains only the expected symbols.

set -eu

cd "$(dirname "$0")/.."
CC=${CC:-cc}
CXX=${CXX:-c++}
NM=${NM:-nm}
tmp=tests/tmp_amalg
status=0

# name, equivalent build macro, C standard, expected symbol, unexpected symbols, excluded units
VARIANTS="\
noxxh3 XXH_NO_XXH3      c99 XXH64_digest XXH3_|XXH128       xxh3_api.h xxh3_static.h xxh3_impl.h
xxh32  XXH_NO_LONG_LONG c90 XXH32_digest XXH64|XXH3_|XXH128 xxh64_api.h xxh64_static.h xxh64_impl.h xxh3_api.h xxh3_static.h xxh3_impl.h
xxh64  XXH_NO_XXH32     c99 XXH64_digest XXH32|XXH3_|XXH128 xxh32_api.h xxh32_static.h xxh32_impl.h xxh3_api.h xxh3_static.h xxh3_impl.h"

rm -rf "$tmp"
mkdir -p "$tmp"
while read -r name macro std present absent units; do
    mkdir -p "$tmp/$name"
    excludes=
    for u in $units; do excludes="$excludes -x $u"; done
    # shellcheck disable=SC2086 # excludes is a list
    sh build/amalgamate.sh $excludes -o "$tmp/$name/xxhash.h" lib/xxhash_root.h 2>/dev/null
done <<EOF
$VARIANTS
EOF

# includes the header several times, in different modes
cat > "$tmp/multi.c" <<EOF
#include XXH_HEADER
#ifndef XXH_STATIC_LINKING_ONLY
#  define XXH_STATIC_LINKING_ONLY
#endif
#include XXH_HEADER
#ifndef XXH_INLINE_ALL
#  define XXH_INLINE_ALL
#endif
#include XXH_HEADER
EOF

# preprocessors may lay out whitespace differently across file boundaries
# (e.g. clang -P), so compare token streams modulo whitespace
normalize() {
    tr '\t' ' ' | sed -e 's/^  *//' -e 's/   */ /g' -e '/^$/d'
}

# compare_pp NAME REFERENCE_HEADER TESTED_HEADER COMPILER CPPFLAGS...
compare_pp() {
    name=$1; ref=$2; new=$3; cc=$4
    shift 4
    if [ "$cc" = "$CXX" ]; then lang=c++; else lang=c; fi
    for side in ref new; do
        if [ "$side" = ref ]; then header=$ref; else header=$new; fi
        # no pipe from the compiler: its failures must stop the script
        $cc -x $lang -E -P "$@" "$header" > "$tmp/raw"
        normalize < "$tmp/raw" > "$tmp/$side.E"
        $cc -x $lang -E -dM "$@" "$header" > "$tmp/raw"
        sort < "$tmp/raw" > "$tmp/$side.dM"
        $cc -x $lang -E -P "$@" -DXXH_HEADER="\"$PWD/$header\"" "$tmp/multi.c" > "$tmp/raw"
        normalize < "$tmp/raw" > "$tmp/$side.multi"
    done
    for mode in E dM multi; do
        if ! cmp -s "$tmp/ref.$mode" "$tmp/new.$mode"; then
            echo "FAIL: $name ($cc $*): $mode output differs from $ref" >&2
            status=1
        fi
    done
}

# note: XXH_IMPLEMENTATION is defined empty, as xxhash.h redefines it in INLINE_ALL mode
for flags in \
    "" \
    "-DXXH_STATIC_LINKING_ONLY" \
    "-DXXH_STATIC_LINKING_ONLY -DXXH_IMPLEMENTATION=" \
    "-DXXH_INLINE_ALL" \
    "-DXXH_PRIVATE_API" \
    "-DXXH_NAMESPACE=NS_ -DXXH_STATIC_LINKING_ONLY -DXXH_IMPLEMENTATION=" \
    "-DXXH_NO_STREAM -DXXH_INLINE_ALL" \
    "-DXXH_NO_LONG_LONG -DXXH_INLINE_ALL"
do
    # shellcheck disable=SC2086 # flags are meant to be split
    compare_pp root xxhash.h lib/xxhash_root.h "$CC" $flags
    while read -r name macro std present absent units; do
        # shellcheck disable=SC2086
        compare_pp "$name" xxhash.h "$tmp/$name/xxhash.h" "$CC" "-D$macro" $flags
    done <<EOF
$VARIANTS
EOF
done
compare_pp root xxhash.h lib/xxhash_root.h "$CXX" -DXXH_INLINE_ALL
while read -r name macro std present absent units; do
    compare_pp "$name" xxhash.h "$tmp/$name/xxhash.h" "$CXX" "-D$macro" -DXXH_INLINE_ALL
done <<EOF
$VARIANTS
EOF

# the noxxh3 variant must be byte-identical to xxhash.h with XXH_NO_XXH3 sections removed
if command -v unifdef >/dev/null 2>&1; then
    unifdef -DXXH_NO_XXH3 xxhash.h > "$tmp/unifdef.h" || [ $? -eq 1 ]
    if ! cmp -s "$tmp/unifdef.h" "$tmp/noxxh3/xxhash.h"; then
        echo "FAIL: noxxh3 variant differs from: unifdef -DXXH_NO_XXH3 xxhash.h" >&2
        status=1
    fi
else
    echo "note: unifdef not found, skipping unifdef comparison"
fi

# each variant must compile cleanly, and contain only the expected symbols
while read -r name macro std present absent units; do
    cp xxhash.c "$tmp/$name/"
    $CC -std="$std" -pedantic -Wall -Wextra -Werror -c "$tmp/$name/xxhash.c" -o "$tmp/$name/xxhash.o"
    $NM "$tmp/$name/xxhash.o" > "$tmp/$name/symbols"
    if grep -E -q "$absent" "$tmp/$name/symbols"; then
        echo "FAIL: $name variant defines unexpected symbols ($absent)" >&2
        status=1
    fi
    if ! grep -q "$present" "$tmp/$name/symbols"; then
        echo "FAIL: $name variant lacks $present" >&2
        status=1
    fi
done <<EOF
$VARIANTS
EOF

if [ "$status" -eq 0 ]; then
    rm -rf "$tmp"
    echo "amalgamation variants: OK"
fi
exit "$status"
